const app = document.getElementById('app');
const money = n => `$${Number(n || 0).toFixed(2)}`;
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
let member = null, tasks = [], videos = [], adminTab = 0, liveVerified = false, signupDraft = {}, deferredInstallPrompt = null, scanTimer = null;
const WITHDRAWAL_OPEN = Date.parse('2027-02-26T00:00:00+03:00');
async function api(path, options = {}) {
  const response = await fetch(path, { credentials: 'same-origin', ...options, headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...(options.headers || {}) } });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error || `Request failed (${response.status}).`);
  return data;
}
function toast(message) { const node = document.getElementById('toast'); if (!node) return; node.textContent = message; node.classList.add('show'); setTimeout(() => node.classList.remove('show'), 2800); }
function modal(html) { document.getElementById('modal').innerHTML = html; document.getElementById('modalbg').style.display = 'flex'; }
function closeModal() { document.getElementById('modalbg').style.display = 'none'; if (scanTimer) { clearInterval(scanTimer); scanTimer = null; } if (window.tvStream) { window.tvStream.getTracks().forEach(track => track.stop()); window.tvStream = null; } }
document.getElementById('modalbg').addEventListener('click', e => { if (e.target === e.currentTarget) closeModal(); });
function installApp() {
  if (window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone) { location.assign('/'); return; }
  if (!deferredInstallPrompt) { toast('This browser cannot start app installation right now.'); return; }
  const promptEvent = deferredInstallPrompt;
  deferredInstallPrompt = null;
  promptEvent.prompt();
  promptEvent.userChoice.then(choice => { if (choice.outcome === 'accepted') { toast('Task Vault is installing.'); setTimeout(() => location.assign('/'), 500); } }).catch(() => {});
}
window.addEventListener('beforeinstallprompt', e => { e.preventDefault(); deferredInstallPrompt = e; });
window.addEventListener('appinstalled', () => { deferredInstallPrompt = null; toast('Task Vault installed.'); });
if ('serviceWorker' in navigator) window.addEventListener('load', () => navigator.serviceWorker.register('/service-worker.js').catch(() => {}));
function topbar({ signedIn = false, admin = false } = {}) {
  return `<header class="topbar"><div class="shell tv-top"><a class="brand" href="/"><span class="logo">✦</span>task vault</a>${signedIn ? '<nav class="topnav"><a href="#earn">Earn</a><a href="#videos">Videos</a><a href="#activity">Activity</a><a href="#invite">Invite friends</a></nav>' : '<span class="tv-tagline">Small tasks. Real progress.</span>'}<div class="profile"><button class="btn btn-soft tv-install" onclick="installApp()">↓ Download app</button>${signedIn ? `<span class="avatar">${esc(member.name.slice(0, 1).toUpperCase())}</span><span class="name">${esc(member.name)}</span><button class="smallbtn" onclick="logout()">Sign out</button>` : admin ? '' : '<button class="btn btn-soft" onclick="openLogin()">Sign in</button>'}</div></div></header>`;
}
function countdownParts(now = Date.now()) {
  let cursor = new Date(now), months = 0;
  while (months < 120) { const next = new Date(cursor); next.setMonth(next.getMonth() + 1); if (next.getTime() > WITHDRAWAL_OPEN) break; cursor = next; months++; }
  const remaining = Math.max(0, WITHDRAWAL_OPEN - cursor.getTime());
  return { months, days: Math.floor(remaining / 86400000), hours: Math.floor(remaining % 86400000 / 3600000), minutes: Math.floor(remaining % 3600000 / 60000), seconds: Math.floor(remaining % 60000 / 1000), done: now >= WITHDRAWAL_OPEN };
}
function countdownMarkup() { return `<div class="tv-live-countdown" data-live-countdown><div><b data-unit="months">00</b><small>MONTHS</small></div><div><b data-unit="days">00</b><small>DAYS</small></div><div><b data-unit="hours">00</b><small>HOURS</small></div><div><b data-unit="minutes">00</b><small>MINUTES</small></div><div><b data-unit="seconds">00</b><small>SECONDS</small></div></div>`; }
function updateLiveCountdown() {
  const parts = countdownParts();
  document.querySelectorAll('[data-live-countdown]').forEach(node => Object.entries(parts).filter(([key]) => key !== 'done').forEach(([key, value]) => { const unit = node.querySelector(`[data-unit="${key}"]`); if (unit) unit.textContent = String(value).padStart(2, '0'); }));
  const target = document.getElementById('withdraw-control');
  if (target && parts.done) target.innerHTML = '<button class="btn btn-light" onclick="openWithdrawal()">Withdraw rewards →</button>';
}
function startLiveCountdown() { if (window.tvCountdownTimer) clearInterval(window.tvCountdownTimer); updateLiveCountdown(); window.tvCountdownTimer = setInterval(updateLiveCountdown, 1000); }
