function questionRow(index) { return `<div class="tv-question"><input class="question-prompt" placeholder="Question ${index + 1}"><input class="question-answer" placeholder="Correct answer"></div>`; }
function openVideoEditor() { modal(`<div class="modal-head"><h2>Add a sponsored video</h2><button class="x" onclick="closeModal()">×</button></div><div class="tv-admin-form"><div class="field"><label>Video title</label><input id="video-title" maxlength="120" placeholder="Video title"></div><div class="field"><label>Direct video URL (HTTPS MP4/WebM)</label><input id="video-url" type="url" placeholder="https://cdn.example.com/video.mp4"></div><div class="field"><label>Description</label><textarea id="video-description" rows="3" placeholder="What should members know about this video?"></textarea></div><div class="tv-question"><div class="field"><label>Full-watch reward (USD)</label><input id="video-watch-reward" type="number" min="0" max="100" step="0.01" value="0.15"></div><div class="field"><label>Correct-quiz reward (USD)</label><input id="video-quiz-reward" type="number" min="0" max="100" step="0.01" value="0.10"></div></div><div class="section-head"><h3 style="margin:0">Optional video questions</h3><button class="btn btn-soft" onclick="addQuestion()">+ Add question</button></div><div id="question-list">${questionRow(0)}</div><div id="video-error" class="tv-error"></div><div class="modal-actions"><button class="btn btn-soft" onclick="closeModal()">Cancel</button><button class="btn btn-green" onclick="saveVideo()">Save as draft</button></div><p class="tv-fine">Use a direct video file URL. YouTube watch-page links do not expose playback completion to this app.</p></div>`); }
function addQuestion() { const list = document.getElementById('question-list'); if (list.children.length >= 5) return toast('A video can have up to five questions.'); list.insertAdjacentHTML('beforeend', questionRow(list.children.length)); }
async function saveVideo() {
  const questions = [...document.querySelectorAll('#question-list .tv-question')].map(row => ({ prompt: row.querySelector('.question-prompt').value.trim(), answer: row.querySelector('.question-answer').value.trim() })).filter(q => q.prompt && q.answer);
  const form = { title: document.getElementById('video-title').value, videoUrl: document.getElementById('video-url').value, description: document.getElementById('video-description').value, watchReward: Number(document.getElementById('video-watch-reward').value), quizReward: Number(document.getElementById('video-quiz-reward').value), questions };
  try { await api('/api/admin/videos', { method: 'POST', body: JSON.stringify(form) }); closeModal(); adminTab = 2; await admin(); toast('Video saved as a draft. Publish it when ready.'); }
  catch (e) { document.getElementById('video-error').textContent = e.message; }
}
async function setVideoStatus(id, status) { try { await api(`/api/admin/videos/${encodeURIComponent(id)}`, { method: 'PATCH', body: JSON.stringify({ status }) }); await admin(); toast(`Video ${status.toLowerCase()}.`); } catch (e) { toast(e.message); } }
async function deleteVideo(id) { if (!confirm('Delete this video and its quiz?')) return; try { await api(`/api/admin/videos/${encodeURIComponent(id)}`, { method: 'DELETE' }); await admin(); } catch (e) { toast(e.message); } }
async function processWithdrawal(id, status) { try { await api(`/api/admin/withdrawals/${encodeURIComponent(id)}`, { method: 'PATCH', body: JSON.stringify({ status }) }); await admin(); toast(`Request ${status.toLowerCase()}.`); } catch (e) { toast(e.message); } }
async function toggleMember(id, status) { try { await api(`/api/admin/users/${encodeURIComponent(id)}`, { method: 'PATCH', body: JSON.stringify({ status }) }); await admin(); } catch (e) { toast(e.message); } }
async function adjustMemberBalance(id, current) { const value = prompt('Set member reward balance in USD', String(current)); if (value === null || !Number.isFinite(Number(value)) || Number(value) < 0) return; try { await api(`/api/admin/users/${encodeURIComponent(id)}`, { method: 'PATCH', body: JSON.stringify({ balance: Number(value) }) }); await admin(); } catch (e) { toast(e.message); } }
async function init() {
  installStyles();
  if (location.pathname.replace(/\/$/, '') === '/admin') { await admin(); return; }
  try { const result = await api('/api/auth/me'); member = result.user; if (!member) { showWelcome(); return; } await loadMember(); }
  catch (e) { showWelcome(`Account service unavailable: ${e.message}`); }
}
window.addEventListener('popstate', init);
init();
